resources:
plugins {
    id 'com.android.application'
}

// build.gradle file content with updated namespaces and resValue strings

// Other configurations...

android {
    namespace 'net.kdt.pojavlaunch'

    compileSdk = 34

    lintOptions {
        abortOnError false
    }

    signingConfigs {
        customDebug {
            storeFile file("debug.keystore")
            storePassword "android"
            keyAlias "androiddebugkey"
            keyPassword "android"
        }
        googlePlayBuild {
            storeFile file("upload.jks")
            storePassword System.getenv("GPLAY_KEYSTORE_PASSWORD")
            keyAlias "upload"
            keyPassword System.getenv("GPLAY_KEYSTORE_PASSWORD")
        }
    }

    defaultConfig {
        applicationId "com.piebite.studio.javalauncher"
        minSdkVersion 21
        targetSdkVersion 34
        versionCode 10000000
        versionName getVersionName()
        multiDexEnabled true
        resValue 'string', 'curseforge_api_key', '"dummy_key"'
    }

    buildTypes {
        debug {
            applicationIdSuffix '.debug'
            minifyEnabled false
            shrinkResources false
            proguardFiles getDefaultProguardFile('proguard-android-optimize.txt'), 'proguard-rules.pro'
            signingConfig signingConfigs.customDebug
            resValue 'string', 'application_package', 'com.piebite.studio.javalauncher.debug'
            resValue 'string', 'storageProviderAuthorities', 'com.piebite.studio.javalauncher.scoped.gamefolder.debug'
            resValue 'string', 'shareProviderAuthority', 'com.piebite.studio.javalauncher.scoped.controlfolder.debug'
        }

        proguard {
            initWith debug
            minifyEnabled true
            shrinkResources true
        }

        proguardNoDebug {
            initWith proguard
            debuggable false
        }

        release {
            minifyEnabled false
            proguardFiles getDefaultProguardFile('proguard-android.txt'), 'proguard-rules.pro'
            resValue 'string', 'storageProviderAuthorities', 'com.piebite.studio.javalauncher.scoped.gamefolder'
            resValue 'string', 'application_package', 'com.piebite.studio.javalauncher'
        }

        gplay {
            initWith release
            signingConfig signingConfigs.googlePlayBuild
            matchingFallbacks = ['release']
        }
    }

    ndkVersion = "25.2.9519653"

    externalNativeBuild {
        ndkBuild {
            path file('src/main/jni/Android.mk')
        }
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_1_8
        targetCompatibility JavaVersion.VERSION_1_8
    }

    bundle {
        language {
            enableSplit = false
        }
    }

    packagingOptions {
        jniLibs {
            useLegacyPackaging = true
        }
        doNotStrip += ["**/libcutils.so"]
        pickFirst '**/libbytehook.so'
    }

    buildFeatures {
        prefab true
        buildConfig true
    }

    buildToolsVersion = '34.0.0'
}

afterEvaluate {
    tasks.matching { it.name == "mergeDebugAssets" }.configureEach {
        dependsOn(
            ":forge_installer:jar",
            ":arc_dns_injector:jar",
            ":lwjgl2_methods_injector:jar",
            ":jre_lwjgl3glfw:jar"
        )
    }
}

dependencies {
    implementation 'javax.annotation:javax.annotation-api:1.3.2'
    implementation 'commons-codec:commons-codec:1.15'
    implementation 'androidx.preference:preference:1.2.0'
    implementation 'androidx.drawerlayout:drawerlayout:1.2.0'
    implementation 'androidx.viewpager2:viewpager2:1.1.0-beta01'
    implementation 'androidx.annotation:annotation:1.5.0'
    implementation "androidx.constraintlayout:constraintlayout:2.1.4"

    implementation fileTree(dir: 'libs', include: ['*.jar', '*.aar'])
    implementation project(":MobileGlues")
}
